 private void SaveVisualDiagnostics() {
  // Opt-in test directory only: diagnostics of Quill's own initial UI. Never inspect other windows.
  try { var details = new List<object>(); void Visit(DependencyObject node) { if (node is TextBlock block) { var face = new Typeface(block.FontFamily,block.FontStyle,block.FontWeight,block.FontStretch); face.TryGetGlyphTypeface(out var glyph); details.Add(new { text = block.Text,font = block.FontFamily.Source,weight = block.FontWeight.ToString(),resolved = glyph == null ? "none" : string.Join(",",glyph.FamilyNames.Values),actual = GlyphNames(VisualTreeHelper.GetDrawing(block)) }); } for (int i = 0;i < VisualTreeHelper.GetChildrenCount(node);i++) Visit(VisualTreeHelper.GetChild(node,i)); } Visit(this); File.WriteAllText(Path.Combine(app.Folder,"actual-font-tree.json"),System.Text.Json.JsonSerializer.Serialize(details,new System.Text.Json.JsonSerializerOptions { WriteIndented = true })); var root = (FrameworkElement)Content; var bitmap = new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(root.ActualWidth),(int)Math.Ceiling(root.ActualHeight),96,96,PixelFormats.Pbgra32); bitmap.Render(root); var png = new System.Windows.Media.Imaging.PngBitmapEncoder(); png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap)); using var file = File.Create(Path.Combine(app.Folder,"actual-window.png")); png.Save(file); } catch (Exception e) { File.WriteAllText(Path.Combine(app.Folder,"visual-diagnostic-error.txt"),e.ToString()); }
 }
 private static string GlyphNames(Drawing? drawing) => drawing switch { GlyphRunDrawing glyph => string.Join(",",glyph.GlyphRun.GlyphTypeface.FamilyNames.Values) + " @ " + glyph.GlyphRun.GlyphTypeface.FontUri, DrawingGroup group => string.Join(";",group.Children.Select(GlyphNames)), _ => "" };
 public void SetNotice(string value) { notice.Text = value; notice.Visibility = string.IsNullOrWhiteSpace(value) ? Visibility.Collapsed : Visibility.Visible; }
 public void RefreshStatus() {
  var state = app.Dictation.State; var shortcut = app.HotkeyLabel;
  liveStatus.Text = state == DictationState.Recording ? C("windows.status.listening","Listening") + " · " + TimeSpan.FromMilliseconds(app.Dictation.ElapsedMs).ToString(@"m\:ss") : state == DictationState.Transcribing ? C("bubble.transcribing","Transcribing…") : shortcut;
  var changed = renderedState != state || renderedShortcut != shortcut; renderedState = state; renderedShortcut = shortcut;
  if (changed) foreach (var update in shortcutPresentations.ToArray()) update();
  if (S.OnboardingComplete && !setupWindow && route == "home") UpdateHomeSession(changed);
  if (app.Dictation.Error.Length > 0) SetNotice(app.ErrorText(app.Dictation.Error));
 }
