 private void Row(StackPanel panel,string icon,string title,string? subtitle,string? value,Action? action = null) {
  if (panel.Children.Count > 0) { var divider = new Border { Height = 1 }; divider.SetResourceReference(Border.BackgroundProperty,"Line"); panel.Children.Add(divider); }
  var grid = new Grid { MinHeight = 42 }; grid.ColumnDefinitions.Add(new() { Width = GridLength.Auto }); grid.ColumnDefinitions.Add(new() { Width = new GridLength(1,GridUnitType.Star) }); grid.ColumnDefinitions.Add(new() { Width = GridLength.Auto });
  var tile = new Border { Width = 30,Height = 30,CornerRadius = new(6),Margin = new(0,0,10,0),VerticalAlignment = VerticalAlignment.Center,Child = new TextBlock { Text = icon,FontFamily = new FontFamily("Segoe Fluent Icons"),FontSize = 20,HorizontalAlignment = HorizontalAlignment.Center,VerticalAlignment = VerticalAlignment.Center } }; tile.SetResourceReference(Border.BackgroundProperty,"BrandSoft"); grid.Children.Add(tile);
  var labels = new StackPanel { VerticalAlignment = VerticalAlignment.Center }; var titleBlock = Text(title,14); titleBlock.FontWeight = FontWeights.Normal; titleBlock.Margin = new(0); labels.Children.Add(titleBlock); if (!string.IsNullOrEmpty(subtitle)) { var sub = Text(subtitle,13,true); sub.FontWeight = FontWeights.Normal; sub.Margin = new(0,3,0,0); labels.Children.Add(sub); } Grid.SetColumn(labels,1); grid.Children.Add(labels);
  if (value != null || action != null) { var trailing = Text((value ?? "") + (action != null ? "  ›" : ""),14,true); trailing.FontWeight = FontWeights.Normal; trailing.Margin = new(10,0,0,0); trailing.VerticalAlignment = VerticalAlignment.Center; Grid.SetColumn(trailing,2); grid.Children.Add(trailing); }
  if (action == null) panel.Children.Add(grid); else { var button = Action(title,action); button.Content = grid; button.Margin = new(0); button.Padding = new(0,6,0,6); button.HorizontalAlignment = HorizontalAlignment.Stretch; button.Background = Brushes.Transparent; panel.Children.Add(button); }
 }
 private Button Action(string label, Action action, bool primary = false) { var b = new Button { HorizontalAlignment = HorizontalAlignment.Left, MaxWidth = 640, Content = new TextBlock { Text = label,FontFamily = Theme.Sans,FontSize = 15,FontWeight = FontWeights.Medium,TextWrapping = TextWrapping.Wrap,TextAlignment = TextAlignment.Center,Foreground = primary ? Brushes.White : (Brush)Application.Current.Resources["BrandInk"] } }; if (primary) { b.SetResourceReference(BackgroundProperty,"Brand"); b.Foreground = Brushes.White; } else { b.Background = Brushes.Transparent; } b.Click += (_,_) => { try { action(); } catch (Exception e) { SetNotice(app.ErrorText(DictationController.Code(e))); } }; System.Windows.Automation.AutomationProperties.SetName(b,label); return b; }
 private Button AsyncAction(string label, Func<Task> action, bool primary = false) { Button? b = null; b = Action(label, async () => { b!.IsEnabled = false; try { await action(); } catch (OperationCanceledException) { } catch (Exception e) { SetNotice(app.ErrorText(DictationController.Code(e))); } finally { b!.IsEnabled = true; } }, primary); return b; }
