 private void Keys(StackPanel targetPanel, bool onboarding) {
  if (onboarding) { GuidedKeys(targetPanel,true,false,() => ShowStep(3)); return; }
  if (!Enum.GetValues<Provider>().Any(provider => app.Secrets.List(provider,S.CustomBaseUrl).Count > 0)) {
   var empty = new StackPanel { MaxWidth = 620,HorizontalAlignment = HorizontalAlignment.Left,Margin = new(0,12,0,24) };
   empty.Children.Add(Text(C("windows.keys.empty_title","Connect your first provider"),22));
   empty.Children.Add(Text(C("windows.keys.empty_body","Add a key from your speech provider to start dictating. Saved keys stay protected on this PC, and you can switch or remove them here."),15,true));
   targetPanel.Children.Add(empty);
  }
  foreach (var provider in Enum.GetValues<Provider>()) {
   var keys = app.Secrets.List(provider,S.CustomBaseUrl); if (keys.Count == 0) continue;
   targetPanel.Children.Add(Text(provider.ToString(),17));
   foreach (var key in keys) { var row = new StackPanel { Margin = new(0,8,0,8) }; row.Children.Add(Text(key.Label + " · ••••" + key.LastFour + (app.Secrets.ActiveId(provider,S.CustomBaseUrl) == key.Id ? " · " + C("settings.keys.active","Active key") : ""),14)); var actions = new WrapPanel(); actions.Children.Add(Action(C("settings.keys.use","Use this key"),() => { app.Secrets.Activate(provider,key.Id,S.CustomBaseUrl); Navigate("keys"); })); actions.Children.Add(Action(C("windows.keys.delete","Delete key"),() => { if (Confirm(C("windows.keys.delete_confirm","Delete this saved key from this PC?"))) { app.Secrets.Delete(provider,key.Id); Navigate("keys"); } })); row.Children.Add(actions); targetPanel.Children.Add(row); }
  }
  targetPanel.Children.Add(Action(C("settings.keys.add","Add key"),() => { Clear(); Back(); Heading(C("settings.keys.add","Add key")); GuidedKeys(page,false,false,() => Navigate("keys")); },true));
 }
