public static class VCardNames {
 public static List<string> Parse(string contents) {
  var unfolded = System.Text.RegularExpressions.Regex.Replace(contents,@"\r?\n[ \t]","");
  return unfolded.Split('\n').Select(l => l.TrimEnd('\r')).Where(l => l.StartsWith("FN:",StringComparison.OrdinalIgnoreCase) || l.StartsWith("FN;",StringComparison.OrdinalIgnoreCase)).Select(l => l[(l.IndexOf(':') + 1)..].Replace(@"\n"," ").Replace(@"\,",",").Replace(@"\;",";").Replace(@"\\",@"\").Trim()).Where(n => n.Length is > 0 and <= 160 && !n.Contains('@')).Distinct(StringComparer.OrdinalIgnoreCase).Take(2000).OrderBy(n => n).ToList();
 }
}
